import ctypes
import numpy as np

# Load the libraries in the specified order
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
# Assuming the function is gsl_block_float_alloc and it allocates a block for float data
# The function signature in C might be: gsl_block_float * gsl_block_float_alloc(size_t n);
gsl.gsl_block_float_alloc.restype = ctypes.POINTER(ctypes.c_float)
gsl.gsl_block_float_alloc.argtypes = [ctypes.c_size_t]

def allocate_float_block(size):
    """Allocate a block of floats using GSL and return as a numpy array."""
    if size <= 0:
        raise ValueError("Size must be greater than 0.")
    block_ptr = gsl.gsl_block_float_alloc(size)
    if not block_ptr:
        raise MemoryError("Failed to allocate memory for float block.")
    # Convert the block to a numpy array
    return np.ctypeslib.as_array((ctypes.c_float * size).from_address(ctypes.addressof(block_ptr.contents)))

def assert_test():
    """Test cases for the allocate_float_block function."""
    # Test allocation of a block of size 5
    block = allocate_float_block(5)
    assert len(block) == 5, "Block size should be 5"

    # Test allocation of a block of size 10
    block = allocate_float_block(10)
    assert len(block) == 10, "Block size should be 10"

    # Test error handling for zero size
    try:
        allocate_float_block(0)
    except ValueError:
        pass
    else:
        assert False, "ValueError should be raised for zero size allocation"

    # Test error handling for negative size
    try:
        allocate_float_block(-1)
    except ValueError:
        pass
    else:
        assert False, "ValueError should be raised for negative size allocation"

if __name__ == "__main__":
    assert_test()
